import { projectEntries } from '../data/projects.js';
import { projectFigures } from '../data/projectFigures.js';
import { projectShowcases } from '../data/projectShowcases.js';
import { researchPublications } from '../data/researchPublications.js';

// Presentation-only lookups. Saved media and the source catalogue stay intact.
function imageKey(value, origin = 'https://exhibition.local') {
  if (typeof value !== 'string' || !value.trim()) return '';
  try {
    const base = new URL(origin);
    const url = new URL(value, base);
    if (!['http:', 'https:'].includes(url.protocol)) return value;
    let path = url.pathname;
    if (path.startsWith('/assets/img/gallery-thumbs/')) {
      path = path.replace('/gallery-thumbs/', '/').replace(/\.webp$/i, '');
    }
    url.searchParams.delete('v');
    const query = url.searchParams.toString();
    const local = url.origin === base.origin || ['www.henryw.me', 'henryw.me'].includes(url.hostname);
    return `${local ? '' : url.origin}${path}${query ? `?${query}` : ''}`;
  } catch { return value; }
}

function imageKeys(image, origin) {
  return [image?.fullSrc, image?.src, image?.smallSrc].map(value => imageKey(value, origin)).filter(Boolean);
}

function sameImage(left, right, origin) {
  const keys = imageKeys(left, origin);
  return imageKeys(right, origin).some(key => keys.includes(key));
}

export function findExhibitionImage(images, reference, origin) {
  return (images || []).find(image => sameImage(image, reference, origin)) || null;
}

const figureNotes = projectEntries.flatMap(entry => [
  ...projectFigures(entry),
  ...(projectShowcases[entry.id]?.scenes || []),
]).filter(figure => figure.caption);
const researchFigures = researchPublications.flatMap(entry => (entry.images || []).map((src, index) => ({
  src: src.startsWith('/') ? src : `/assets/img/${src}.png`,
  label: entry.figureLabels?.[index] || '',
}))).filter(figure => figure.label);

const text = value => typeof value === 'string' ? value.trim() : '';

function descriptiveAlt(value, source) {
  const alt = text(value);
  if (!alt || [source?.title, source?.source_id].some(title => text(title).toLowerCase() === alt.toLowerCase())) return '';
  if (/^(?:figure|image|photo(?:graph)?|picture)\s*\d*$/i.test(alt) || /^\d+$/.test(alt)) return '';
  if (/^(?:https?:|data:|\/assets\/)/i.test(alt) || /\.(?:avif|gif|jpe?g|png|svg|webp)(?:\?.*)?$/i.test(alt)) return '';
  return alt;
}

export function exhibitionImageDetails(source, image, origin) {
  if (!image) return { caption: '', label: '', alt: '' };
  const saved = findExhibitionImage(source?.media, image, origin);
  const note = figureNotes.find(figure => sameImage(figure, image, origin)) || researchFigures.find(figure => sameImage(figure, image, origin));
  const caption = text(image.caption) || text(image.description) || text(saved?.caption) || text(saved?.description)
    || text(note?.caption) || descriptiveAlt(image.alt || saved?.alt, source);
  const label = text(image.label) || text(saved?.label) || text(note?.label);
  const alt = descriptiveAlt(image.alt || saved?.alt, source) || text(note?.alt) || caption || text(source?.title);
  return { caption, label: label === caption || /^Figure \d+$/i.test(label) ? '' : label, alt };
}

const svgDetails = new Map();

export function exhibitionSvgAsset(image, origin = 'https://exhibition.local') {
  try {
    const base = new URL(origin);
    const url = new URL(image?.fullSrc || image?.src, base);
    if (url.origin !== base.origin && !['www.henryw.me', 'henryw.me'].includes(url.hostname)) return '';
    return /^\/assets\/img\/.+\.svg$/i.test(url.pathname) ? url.pathname + url.search : '';
  } catch { return ''; }
}

export async function loadExhibitionSvgDetails(image, origin) {
  const asset = exhibitionSvgAsset(image, origin);
  if (!asset) return null;
  if (!svgDetails.has(asset)) {
    // Read the image's own accessible description only when no saved caption
    // exists. The document stays detached and is never inserted into the page.
    svgDetails.set(asset, (async () => {
      try {
        const response = await fetch(asset);
        if (!response.ok) return null;
        const doc = new DOMParser().parseFromString(await response.text(), 'image/svg+xml');
        if (doc.querySelector('parsererror') || doc.documentElement.localName !== 'svg') return null;
        const children = [...doc.documentElement.children];
        const caption = text(children.find(child => child.localName === 'desc')?.textContent);
        const label = text(children.find(child => child.localName === 'title')?.textContent);
        return caption || label ? { caption: caption || label, label: caption ? label : '', alt: label || caption } : null;
      } catch { return null; }
    })());
    if (svgDetails.size > 128) svgDetails.delete(svgDetails.keys().next().value);
  }
  return svgDetails.get(asset);
}
